      items: this.items(pid), free: this.freeLeft(pid), dailyDone: this.calRow(pid).day === bkkDay(), unread: this.unread(pid), ...this.dmCap(pid), v: VERSION, login: this.providers(pid), cal: this.calInfo(pid),
      name: (this.sql.exec(`SELECT name FROM names WHERE pid=?`, pid).toArray()[0] || {}).name || null, renameFree: this.renameInfo(pid) === 0,
