      if (pid === r.host && !r.seats.includes(pid)) { const i = r.seats[0] ? this.freeSeat(0) : 0; if (i >= 0) r.seats[i] = pid; }
      try { ws.send(json({ t: "crhist", chat: r.chat })); } catch (e) {}
      if (isNew) this.sys(`👋 ${r.members[pid].name} เข้าห้อง`, { enter: pid, bn: r.members[pid].bn });
