/* ตัวกลางคุยกับ Cloudflare SFU (secret อยู่ฝั่ง server เท่านั้น) */
async function sfuRoute(request, env, pid) {
  const app = env.SFU_APP_ID, sec = env.SFU_SECRET; if (!app || !sec) return J({ error: "nosfu" });
  let o = {}; try { o = await request.json(); } catch (e) {}
  const base = `https://rtc.live.cloudflare.com/v1/apps/${app}`, H = { authorization: `Bearer ${sec}`, "content-type": "application/json" };
  const sid = String(o.sid || ""), body = o.body ? JSON.stringify(o.body) : undefined;
  let r;
  if (o.op === "new") { if (!(await hub(env).auth(pid, String(o.key || "")))) return J({ error: "auth" }); r = await fetch(`${base}/sessions/new`, { method: "POST", headers: H }); }
  else {
    if (!/^[\w-]{8,100}$/.test(sid)) return J({ error: "bad sid" });
    if (o.op === "tracks") r = await fetch(`${base}/sessions/${sid}/tracks/new`, { method: "POST", headers: H, body });
    else if (o.op === "reneg") r = await fetch(`${base}/sessions/${sid}/renegotiate`, { method: "PUT", headers: H, body });
    else if (o.op === "close") r = await fetch(`${base}/sessions/${sid}/tracks/close`, { method: "PUT", headers: H, body });
    else return J({ error: "bad op" });
  }
  const j = await r.json().catch(() => ({})); if (!r.ok) return J({ error: "sfu " + r.status, detail: j });
  return J(j);
}

async function iceServers(env) {
  const stun = [{ urls: ["stun:stun.cloudflare.com:3478"] }];
  if (!env.TURN_KEY_ID || !env.TURN_KEY_API_TOKEN) return { iceServers: stun, turn: false };
  if (iceCache && iceCache.exp > Date.now()) return iceCache.v;
  try {
    const r = await fetch(`https://rtc.live.cloudflare.com/v1/turn/keys/${env.TURN_KEY_ID}/credentials/generate-ice-servers`, { method: "POST", headers: { Authorization: `Bearer ${env.TURN_KEY_API_TOKEN}`, "Content-Type": "application/json" }, body: JSON.stringify({ ttl: 86400 }) });
    if (!r.ok) throw new Error("turn " + r.status);
    const j = await r.json();
    const v = { iceServers: (j.iceServers || []).map((s) => ({ ...s, urls: [].concat(s.urls).filter((u) => !/:53\b/.test(u)) })), turn: true };
    iceCache = { v, exp: Date.now() + 6 * 3600 * 1000 }; return v;
  } catch (e) { return { iceServers: stun, turn: false }; }
}

/* =================== ล็อกอิน LINE / Google (OAuth) =================== */
const AUTH = {
  line: { authUrl: "https://access.line.me/oauth2/v2.1/authorize", tokenUrl: "https://api.line.me/oauth2/v2.1/token", scope: "profile openid", id: (e) => e.LINE_CHANNEL_ID, secret: (e) => e.LINE_CHANNEL_SECRET },
  google: { authUrl: "https://accounts.google.com/o/oauth2/v2/auth", tokenUrl: "https://oauth2.googleapis.com/token", scope: "openid email profile", id: (e) => e.GOOGLE_CLIENT_ID, secret: (e) => e.GOOGLE_CLIENT_SECRET },
};
const back = (url, o) => Response.redirect(`${url.origin}/#login=${encodeURIComponent(btoa(unescape(encodeURIComponent(JSON.stringify(o)))))}`, 302);
function jwtPayload(t) { try { const b = t.split(".")[1].replace(/-/g, "+").replace(/_/g, "/"); return JSON.parse(decodeURIComponent(escape(atob(b + "===".slice((b.length + 3) % 4))))); } catch (e) { return null; } }
async function authRoute(url, env) {
  const [, , prov, step] = url.pathname.split("/"); const P = AUTH[prov];
  if (!P) return new Response("not found", { status: 404 });
  const cid = P.id(env), sec = P.secret(env), cb = `${url.origin}/auth/${prov}/callback`;
  if (!cid || !sec) return back(url, { error: `ยังไม่ได้ตั้งค่าล็อกอิน ${prov}` });
  const H = hub(env);
  if (step === "start") {
    const pid = url.searchParams.get("pid") || "", key = url.searchParams.get("key") || "", ref = (url.searchParams.get("ref") || "").replace(/[^A-Za-z0-9]/g, "").slice(0, 10);
    if (!PID_RE.test(pid)) return back(url, { error: "bad pid" });
    const r = await H.newState(pid, key, prov, ref); if (!r.state) return back(url, { error: "ยืนยันตัวตนไม่ผ่าน" });
    const q = new URLSearchParams({ response_type: "code", client_id: cid, redirect_uri: cb, state: r.state, scope: P.scope });
    if (prov === "google") q.set("prompt", "select_account");
    return Response.redirect(`${P.authUrl}?${q}`, 302);
  }
  if (step === "callback") {
    const code = url.searchParams.get("code"), stt = url.searchParams.get("state");
    if (!code || !stt) return back(url, { error: "ยกเลิกการเข้าสู่ระบบ" });
    const s = await H.takeState(stt); if (!s || s.prov !== prov) return back(url, { error: "ลิงก์หมดอายุ ลองใหม่อีกครั้ง" });
    const tr = await fetch(P.tokenUrl, { method: "POST", headers: { "content-type": "application/x-www-form-urlencoded" }, body: new URLSearchParams({ grant_type: "authorization_code", code, redirect_uri: cb, client_id: cid, client_secret: sec }) });
    const tj = await tr.json().catch(() => ({}));
    if (!tr.ok || !tj.id_token) return back(url, { error: "เข้าสู่ระบบไม่สำเร็จ (" + (tj.error || tr.status) + ")" });
    const pl = jwtPayload(tj.id_token); if (!pl || !pl.sub) return back(url, { error: "อ่านข้อมูลบัญชีไม่ได้" });
    if (pl.aud !== cid && !(Array.isArray(pl.aud) && pl.aud.includes(cid))) return back(url, { error: "บัญชีไม่ตรงกับแอป" });
    const res = await H.link(`${prov}:${pl.sub}`, s.pid, s.ref, pl.name || "");
    return back(url, { ok: 1, prov, pid: res.pid, key: res.key, switched: res.switched, isNew: res.isNew, name: res.name, av: res.av });
  }
  return new Response("not found", { status: 404 });
}

function legalPage(priv) {
  const body = priv
    ? `<h1>นโยบายความเป็นส่วนตัว · Spy Hunt</h1>
<p>เมื่อคุณเข้าสู่ระบบด้วย LINE หรือ Google เราเก็บเฉพาะ <b>รหัสบัญชี (ID) และชื่อที่แสดง</b> เพื่อผูกเหรียญ ของที่ซื้อ และอันดับไว้กับบัญชีของคุณ</p>
<p>เราไม่เก็บรหัสผ่าน ไม่โพสต์อะไรแทนคุณ ไม่ขายหรือส่งข้อมูลให้บุคคลอื่น เสียงในห้องเกมส่งตรงระหว่างผู้เล่นและไม่ถูกบันทึก</p>
<p>ข้อมูลในเกม (ชื่อ รูปโปรไฟล์ เหรียญ ประวัติ แชท) เก็บบน Cloudflare เพื่อให้เกมทำงาน หากต้องการลบบัญชี ติดต่อ nyg.suthiwong@gmail.com</p>`
    : `<h1>ข้อตกลงการใช้งาน · Spy Hunt</h1>
<p>Spy Hunt เป็นเกมปาร์ตี้ออนไลน์ อยู่ในช่วงทดสอบ (BETA) ระบบและไอเท็มอาจมีการเปลี่ยนแปลง</p>
<p>เหรียญและไอเท็มใช้ได้ในเกมเท่านั้น แลกเป็นเงินไม่ได้ ห้ามใช้ถ้อยคำหยาบคาย คุกคาม หรือโกงระบบ ผู้ฝ่าฝืนอาจถูกระงับบัญชี</p>
<p>ติดต่อ nyg.suthiwong@gmail.com</p>`;
  return `<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Spy Hunt</title>
<style>body{font-family:system-ui,sans-serif;background:#120609;color:#eee;max-width:640px;margin:0 auto;padding:24px;line-height:1.7}h1{color:#ffd66b;font-size:22px}a{color:#ff6b81}</style></head>
<body>${body}<p><a href="/">← กลับเข้าเกม</a></p></body></html>`;
}

/* =================== Worker หลัก =================== */
const J = (o, s = 200) => new Response(JSON.stringify(o), { status: s, headers: { "content-type": "application/json", "cache-control": "no-store" } });
export default {
  async fetch(request, env) {
    const url = new URL(request.url); const q = url.searchParams;
    if (url.pathname === "/ws") {
      const no = q.get("room") || "", code = q.get("code") || "";
      if (!/^\d{4}$/.test(no) || !/^\d{4}$/.test(code)) return new Response("bad room", { status: 400 });
      return env.ROOMS.get(env.ROOMS.idFromName(`${no}-${code}`)).fetch(request);
    }
    if (url.pathname === "/ice") return J(await iceServers(env));
    if (url.pathname === "/cr/ws") { const no = q.get("no") || ""; if (!/^\d{4}$/.test(no)) return new Response("bad", { status: 400 }); return env.CR.get(env.CR.idFromName("cr-" + no)).fetch(request); }
    if (url.pathname === "/api/sfu" && request.method === "POST") { const pid = q.get("pid") || ""; if (!PID_RE.test(pid)) return J({ error: "bad pid" }); return sfuRoute(request, env, pid); }
    if (url.pathname === "/api/version") return J({ v: VERSION });
    if (url.pathname === "/privacy" || url.pathname === "/terms") return new Response(legalPage(url.pathname === "/privacy"), { headers: { "content-type": "text/html; charset=utf-8" } });
    if (url.pathname.startsWith("/auth/")) return authRoute(url, env);   // ไม่แตะ Durable Object ไม่กินโควต้า
    if (url.pathname.startsWith("/avatar/")) {
      const pid = url.pathname.slice(8); if (!PID_RE.test(pid)) return new Response("bad", { status: 400 });
      const d = await hub(env).getAvatar(pid); if (!d) return new Response("none", { status: 404 });
      const [head, b64] = d.split(","); const bin = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
      return new Response(bin, { headers: { "content-type": head.slice(5, head.indexOf(";")), "cache-control": "public, max-age=31536000, immutable" } });
    }
    if (url.pathname === "/api/avatar" && request.method === "POST") {
      const pid = q.get("pid") || ""; if (!PID_RE.test(pid)) return J({ error: "bad pid" }, 400);
      const body = await request.text(); if (body.length > 70000) return J({ error: "too big" }, 413);
      let o; try { o = JSON.parse(body); } catch { return J({ error: "bad json" }, 400); }
      const r = await hub(env).setAvatar(pid, String(o.key || ""), String(o.data || ""));
      return J(r, r.error ? 400 : 200);
    }
    if (url.pathname.startsWith("/api/")) {
      const pid = q.get("pid") || ""; const H = hub(env);
      if (pid && !PID_RE.test(pid)) return J({ error: "bad pid" }, 400);
      try {
        if (url.pathname === "/api/me") { const cc = (request.cf && request.cf.country) || null; const [pf, st, fd] = [await H.profile(pid), await H.presence(pid, cc), await H.feed(parseInt(q.get("since"), 10) || 0)]; return J({ ...pf, ...st, feed: fd, cc }); }
        if (url.pathname === "/api/rank") return J(await H.ranking(pid, q.get("by") || "charm", q.get("cc") || ""));
        if (url.pathname === "/api/daily") return J(await H.claimDaily(pid, q.get("key") || ""));
        if (url.pathname === "/api/cr/list") return J(await H.crList());
        if (url.pathname === "/api/cr/create") return J(await H.crCreate(pid, q.get("key") || "", q.get("name") || "", q.get("e") || "", q.get("cap") || "", q.get("pw") || ""));
        if (url.pathname === "/api/uid") return J(await H.setUid(pid, q.get("key") || "", q.get("uid") || ""));
        if (url.pathname === "/api/find") return J(await H.findUser(pid, q.get("key") || "", q.get("uid") || ""));
        if (url.pathname === "/api/friends") return J(await H.friendList(pid, q.get("key") || ""));
        if (url.pathname === "/api/friend/ok") return J(await H.friendOk(pid, q.get("key") || "", q.get("with") || ""));
        if (url.pathname === "/api/friend/no") return J(await H.friendNo(pid, q.get("key") || "", q.get("with") || ""));
        if (url.pathname === "/api/friend/req" && request.method === "POST") { let o = {}; try { o = await request.json(); } catch (e) {} return J(await H.friendReq(pid, String(o.key || ""), String(o.to || ""), String(o.text || ""))); }
        if (url.pathname === "/api/rename") return J(await H.rename(pid, q.get("key") || "", q.get("name") || ""));
        if (url.pathname === "/api/ref") return J(await H.refInfo(pid, q.get("key") || ""));
        if (url.pathname === "/api/dm/list") return J(await H.dmList(pid, q.get("key") || ""));
        if (url.pathname === "/api/dm/thread") return J(await H.dmThread(pid, q.get("key") || "", q.get("with") || ""));
        if (url.pathname === "/api/dm/send" && request.method === "POST") { let o = {}; try { o = await request.json(); } catch (e) {} return J(await H.dmSend(pid, String(o.key || ""), String(o.to || ""), String(o.text || ""))); }
        if (url.pathname === "/api/history") return J(await H.history(pid, q.get("key") || ""));
        if (url.pathname === "/api/buy") return J(await H.buy(pid, q.get("key") || "", q.get("kind") || "", q.get("id") || ""));
        if (url.pathname === "/api/equip") return J(await H.equip(pid, q.get("key") || "", q.get("kind") || "", q.get("id") || ""));
        if (url.pathname === "/api/stats") return J(pid ? await H.presence(pid) : await H.stats());
        if (url.pathname === "/api/random") return J({ room: await H.random(q.get("ex") || "") });
        if (url.pathname === "/api/cancreate") { const n = Math.min(12, Math.max(3, parseInt(q.get("size"), 10) || 6)); return J(await H.canCreate(n)); }
      } catch (e) { return J({ error: String(e && e.message || e) }, 500); }
      return J({ error: "not found" }, 404);
    }
    return new Response(HTML, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache" } });
  },
};
